/* @autogenerated */
package net.civeira.phylax.feature.oauth.profile.infrastructure.driven;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.oauth.profile.domain.ActiveSession;
import net.civeira.phylax.testing.sql.H2Database;

/** The active sessions of the profile, listed and revoked with the production sql on h2. */
class SessionsAdapterUnitTest {
  private H2Database db;
  private SessionsAdapter adapter;

  @BeforeEach
  void setUp() {
    db = new H2Database();
    adapter = new SessionsAdapter(db.dataSource());
  }

  private void session(String id, String userUid, String username, String expiration,
      String revokedAt, String lastUsedAt) {
    db.execute("INSERT INTO _oauth_session (session, user_uid, expiration, client_id, issuer,"
        + " auth_data, csid, revoked_at, ip_address, user_agent, last_used_at, client_name,"
        + " auth_time) VALUES ('" + id + "', '" + userUid + "', " + expiration + ", 'web',"
        + " 'issuer', '{\"username\":\"" + username + "\"}', 'csid', " + revokedAt
        + ", '10.0.0.1', 'Firefox', " + lastUsedAt + ", 'Web app', CURRENT_TIMESTAMP)");
  }

  @Test
  @DisplayName("Only the live sessions of the user are listed, the most recently used first")
  void lists_live_sessions() {
    String future = "DATEADD('HOUR', 1, CURRENT_TIMESTAMP)";
    session("old", "user-1", "alice", future, "NULL", "DATEADD('MINUTE', -30, CURRENT_TIMESTAMP)");
    session("recent", "user-1", "alice", future, "NULL", "CURRENT_TIMESTAMP");
    session("by-name", "legacy", "alice", future, "NULL", "DATEADD('HOUR', -2, CURRENT_TIMESTAMP)");
    session("expired", "user-1", "alice", "DATEADD('HOUR', -1, CURRENT_TIMESTAMP)", "NULL", "NULL");
    session("revoked", "user-1", "alice", future, "CURRENT_TIMESTAMP", "NULL");
    session("other", "user-2", "bob", future, "NULL", "NULL");

    List<ActiveSession> sessions = adapter.listByUser("user-1", "alice");

    Assertions.assertEquals(List.of("recent", "old", "by-name"),
        sessions.stream().map(ActiveSession::getSessionId).toList());
    ActiveSession first = sessions.get(0);
    Assertions.assertEquals("web", first.getClientId());
    Assertions.assertEquals("Web app", first.getClientName().orElseThrow());
    Assertions.assertEquals("10.0.0.1", first.getIpAddress().orElseThrow());
    Assertions.assertEquals("Firefox", first.getUserAgent().orElseThrow());
    Assertions.assertTrue(first.getLastUsedAt().isPresent());
    Assertions.assertNotNull(first.getExpiration());
    Assertions.assertTrue(first.getCreatedAt().isPresent(), "The time of the login");
  }

  @Test
  @DisplayName("A revoked session is no longer listed")
  void revoke() {
    session("s1", "user-1", "alice", "DATEADD('HOUR', 1, CURRENT_TIMESTAMP)", "NULL", "NULL");

    adapter.revoke("s1");

    Assertions.assertTrue(adapter.listByUser("user-1", "alice").isEmpty());
    Assertions.assertEquals(1, db.count("_oauth_session", "revoked_at IS NOT NULL"));
  }
}
